vertex:
#version 300 es
precision highp float;
precision highp int;
in vec3 aVertexPosition;
in vec2 aTextureCoord;
uniform vec2 uResolution;
uniform vec2 uPos;
uniform float uTime;
uniform float uScale;
uniform vec3 uRotation;
uniform float uWidth;
uniform float uThickness;
uniform float uOpening;
uniform float uBreath;
uniform float uBreathSpeed;
out vec2 vTextureCoord;
out vec3 vNormal;
out vec3 vWorld;
out vec2 vSurface;
const float TAU = 6.28318530718;
mat3 turn(vec3 a) {
  vec3 c = cos(a);
  vec3 s = sin(a);
  return mat3(c.z,-s.z,0.0,s.z,c.z,0.0,0.0,0.0,1.0) * mat3(c.y,0.0,s.y,0.0,1.0,0.0,-s.y,0.0,c.y) * mat3(1.0,0.0,0.0,0.0,c.x,-s.x,0.0,s.x,c.x);
}
vec3 surface(float angle, float crossAngle, float phase) {
  float ca = cos(angle);
  float sa = sin(angle);
  float doubleWave = sin(2.0 * angle + 0.4);
  float openRadius = 0.75 + uOpening * 0.65;
  vec3 center = vec3(1.85 * ca * openRadius, 1.06 * sa, 0.38 * doubleWave);
  vec3 tangent = normalize(vec3(-1.85 * sa * openRadius, 1.06 * ca, 0.76 * cos(2.0 * angle + 0.4)));
  vec3 radial = normalize(vec3(ca / 1.85, sa / 1.06, 0.0));
  vec3 binormal = normalize(cross(radial, tangent));
  radial = normalize(cross(tangent, binormal));
  float twist = angle + 0.58 * doubleWave + 0.2 + uBreath * 0.65 * sin(phase + angle);
  float wide = (0.14 + uWidth * 0.52) * (0.82 + 0.18 * cos(angle - 0.5));
  float thick = 0.012 + 0.075 * uThickness;
  vec2 section = vec2(cos(crossAngle), sin(crossAngle));
  section = sign(section) * pow(abs(section), vec2(0.38));
  float sx = section.x * wide;
  float sy = section.y * thick;
  return center + radial * (sx * cos(twist) - sy * sin(twist)) + binormal * (sx * sin(twist) + sy * cos(twist));
}
void main() {
  float time = uTime * 0.025;
  float phase = time * (0.28 + 0.72 * uBreathSpeed);
  float angle = aTextureCoord.x * TAU;
  float crossAngle = aTextureCoord.y * TAU;
  vec3 point = surface(angle, crossAngle, phase);
  vec3 du = surface(angle + 0.001, crossAngle, phase) - surface(angle - 0.001, crossAngle, phase);
  vec3 dv = surface(angle, crossAngle + 0.001, phase) - surface(angle, crossAngle - 0.001, phase);
  vec3 normal = normalize(cross(du, dv));
  mat3 rotation = turn(uRotation * TAU);
  point = rotation * point;
  normal = rotation * normal;
  float size = 0.65 + 0.95 * uScale;
  point *= size;
  float horizontalFit = min(uResolution.x / (uResolution.y * 1.6), 1.0);
  point.x *= horizontalFit;
  normal.x /= horizontalFit;
  float viewDistance = 4.8 - point.z;
  float focal = 3.7;
  float aspect = uResolution.x / uResolution.y;
  vec2 projected = vec2(point.x * focal / aspect, point.y * focal);
  vec2 anchor = (uPos - 0.5) * 2.0;
  float nearPlane = 0.1;
  float farPlane = 20.0;
  float depth = ((farPlane + nearPlane) / (farPlane - nearPlane)) * viewDistance - (2.0 * farPlane * nearPlane) / (farPlane - nearPlane);
  gl_Position = vec4(projected + anchor * viewDistance, depth, viewDistance);
  gl_Position.xy += aVertexPosition.xy * 0.00000001;
  vWorld = point;
  vNormal = normal;
  vTextureCoord = aTextureCoord;
  vSurface = vec2(angle, crossAngle);
}

fragment:
#version 300 es
precision highp float;
precision highp int;
in vec2 vTextureCoord;
in vec3 vNormal;
in vec3 vWorld;
in vec2 vSurface;
uniform vec3 uCopperColor;
uniform vec3 uEdgeColor;
uniform float uBrightness;
uniform float uRoughness;
uniform float uTime;
uniform float uLightSpeed;
uniform float uFilament;
out vec4 fragColor;
float studio(vec3 ray, vec3 axis, float sharpness) {
  return pow(max(dot(ray, normalize(axis)), 0.0), sharpness);
}
float softbox(vec3 ray, vec3 direction, vec2 dimensions, float softness) {
  vec3 axis = normalize(direction);
  vec3 horizontal = normalize(cross(axis, vec3(0.0, 1.0, 0.0)));
  vec3 vertical = cross(horizontal, axis);
  float front = dot(ray, axis);
  vec2 uv = vec2(dot(ray, horizontal), dot(ray, vertical)) / max(front, 0.001);
  vec2 distanceToBox = abs(uv) - dimensions;
  float outside = length(max(distanceToBox, 0.0));
  float inside = min(max(distanceToBox.x, distanceToBox.y), 0.0);
  float distanceToEdge = outside + inside;
  return (1.0 - smoothstep(0.0, softness, distanceToEdge)) * step(0.0, front);
}
void main() {
  float time = uTime * 0.025;
  float phase = time * (0.18 + uLightSpeed * 0.82);
  vec3 normal = normalize(vNormal);
  vec3 view = normalize(vec3(0.0, 0.0, 4.8) - vWorld);
  if (dot(normal, view) < 0.0) {
    normal *= -1.0;
  }
  vec3 reflected = reflect(view * -1.0, normal);
  float roughness = 0.1 + uRoughness * 0.65;
  float exponent = mix(110.0, 15.0, roughness);
  float softness = 0.025 + roughness * 0.18;
  float key = softbox(reflected, vec3(-0.65, 0.55, 1.45), vec2(0.065, 1.3), softness);
  float wide = studio(reflected, vec3(0.8, 0.25, 1.0), 5.0);
  float strip = softbox(reflected, vec3(1.0, -0.2, 0.65), vec2(0.045, 1.4), softness);
  float moving = softbox(reflected, vec3(0.45 * sin(phase), -0.55, 1.0), vec2(1.25, 0.025), softness * 1.4);
  float diffuse = max(dot(normal, normalize(vec3(-0.45, 0.8, 1.2))), 0.0);
  float grazing = pow(1.0 - max(dot(normal, view), 0.0), 3.0);
  vec3 copper = pow(uCopperColor, vec3(2.2));
  vec3 edge = pow(uEdgeColor, vec3(2.2));
  vec3 radiance = copper * (0.015 + 0.10 * diffuse + 0.24 * wide);
  radiance += mix(copper, edge, 0.45) * key * 1.4;
  radiance += mix(copper, edge, 0.3) * strip * 2.0;
  radiance += copper * (moving * 1.2 + grazing * 0.25);
  float innerEdge = pow(max(-cos(vSurface.y), 0.0), 10.0);
  float flow = 0.52 + 0.48 * cos(vSurface.x * 2.0 - phase);
  float seam = innerEdge * (0.4 + 0.6 * flow);
  float ribbonCoordinate = cos(vSurface.y);
  float channels = pow(0.5 + 0.5 * sin(ribbonCoordinate * 28.0 + 1.25 * sin(vSurface.x * 2.0 - phase)), 12.0);
  float moltenFace = pow(max(sin(vSurface.y), 0.0), 0.7);
  float heat = moltenFace * (0.22 + 0.24 * flow + channels * 0.35);
  radiance += copper * heat * uFilament * 1.8;
  radiance += edge * seam * uFilament * 1.6;
  radiance *= 0.45 + uBrightness * 1.8;
  vec3 color = pow(radiance / (1.0 + radiance), vec3(0.454545));
  fragColor = vec4(color, 1.0);
}
